import styles from "./carousel.module.less";
import React, { LegacyRef, PropsWithChildren, useCallback, useEffect, useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import Icon from "@/core/components/primitives/icon/icon";
import { motion } from "framer-motion";
import { multipleClassNames } from "@/core/helpers";

type Props = {
  elementRef?: LegacyRef<HTMLDivElement> | null;
  className?: string;
  classNameList?: string;
  classNameListItem?: string;
  classNamePrevBtn?: string;
  classNameNextBtn?: string;
  classNameNavDotsWrapper?: string;
  navDots?: boolean;
};

const Carousel = (props: PropsWithChildren<Props>) => {
  const {
    elementRef = null,
    className = "",
    classNameList = "",
    classNameListItem = "",
    classNamePrevBtn = "",
    classNameNextBtn = "",
    classNameNavDotsWrapper = "",
    navDots = false,
    children,
  } = props;

  const [showPrevious, setShowPrevious] = useState(false);
  const [showNext, setShowNext] = useState(false);
  const [showNavDots, setShowNavDots] = useState(false);
  const listRef = useRef<HTMLUListElement>(null);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const [carouselPage, setCarouselPage] = useState(1);
  const [carouselLastPage, setCarouselLastPage] = useState(0);
  const { t } = useTranslation();

  const isSingleChild = React.Children.count(children) === 1;

  //Navigate the carousel in the specified direction, one viewable width at a time.
  const navigate = useCallback((direction: "prev" | "next") => {
    if (!listRef.current || !wrapperRef.current) {
      return;
    }

    const wrapperOffsetWidth = wrapperRef.current.offsetWidth;
    const listScrollLeft = listRef.current.scrollLeft;
    const maxScrollLeft = listRef.current.scrollWidth - wrapperRef.current.offsetWidth;

    let targetScrollLeft;
    if (direction === "next") {
      targetScrollLeft = Math.min(listScrollLeft + wrapperOffsetWidth, maxScrollLeft);
    } else {
      targetScrollLeft = Math.max(listScrollLeft - wrapperOffsetWidth, 0);
    }

    listRef.current.scrollLeft = targetScrollLeft;
  }, []);

  const updateControls = useCallback(() => {
    if (!listRef.current || !wrapperRef.current) {
      return;
    }

    const listScrollLeft = listRef.current.scrollLeft;
    const listScrollRight = listRef.current.scrollWidth - listScrollLeft - wrapperRef.current.offsetWidth;
    const listScrollWidth = listRef.current.scrollWidth;
    const style = window.getComputedStyle(listRef.current);
    const adjustByLeft = style.marginLeft !== "auto" ? parseInt(style.marginLeft, 10) : 0;
    const adjustByRight = style.marginRight !== "auto" ? parseInt(style.marginRight, 10) : 0;
    const wrapperOffsetWidth = wrapperRef.current.offsetWidth - adjustByLeft - adjustByRight;
    const lastPage = Math.ceil(listScrollWidth / wrapperOffsetWidth);

    setShowNext(listScrollRight > 1);
    setShowPrevious(listScrollLeft > 1);

    const page = Math.round(listScrollLeft / wrapperOffsetWidth) + 1;

    setCarouselPage(page > lastPage || listScrollRight < 1 ? lastPage : page);
    setCarouselLastPage(lastPage);

    const totalChildrenWidth = Array.from(listRef.current.children).reduce((acc, child) => {
      return acc + (child as HTMLLIElement).offsetWidth;
    }, 0);

    setShowNavDots(totalChildrenWidth > wrapperRef.current.offsetWidth);
  }, []);

  useEffect(() => {
    updateControls();
  }, [updateControls]);

  useEffect(() => {
    if (!listRef.current) return undefined;

    listRef.current.addEventListener("scroll", updateControls);
    listRef.current.addEventListener("touchmove", updateControls);

    const handleResize = () => {
      updateControls();
    };

    window.addEventListener("resize", handleResize);

    const listRefCurrent = listRef.current;

    return () => {
      listRefCurrent?.removeEventListener("scroll", updateControls);
      listRefCurrent?.removeEventListener("touchmove", updateControls);
      window.removeEventListener("resize", handleResize);
    };
  }, [updateControls]);

  const handleNavDotClick = useCallback((page: number) => {
    if (!listRef.current || !wrapperRef.current) {
      return;
    }

    const wrapperOffsetWidth = wrapperRef.current.offsetWidth;
    const targetScrollLeft = (page - 1) * wrapperOffsetWidth;

    listRef.current.scrollLeft = targetScrollLeft;
  }, []);

  if (!children) {
    return null;
  }

  return (
    <div className={styles.wrapper} ref={elementRef}>
      <div className={styles.carouselWrapper}>
        {showPrevious && (
          <button
            data-contentful-label-id="previous"
            className={multipleClassNames(styles.prevButton, classNamePrevBtn)}
            onClick={() => navigate("prev")}
            aria-label={t("previous")}
            title={t("previous")}
          >
            <Icon name="chevron-left" />
          </button>
        )}
        <div className={multipleClassNames(styles.innerWrapper, className)} ref={wrapperRef}>
          <ul
            ref={listRef}
            className={multipleClassNames(styles.list, isSingleChild && styles.singleItem, classNameList)}
          >
            {React.Children.map(children, (child, i) => (
              <li key={i} className={multipleClassNames(styles.listItem, classNameListItem)}>
                {child}
              </li>
            ))}
          </ul>
        </div>
        {showNext && (
          <button
            data-contentful-label-id="next"
            className={multipleClassNames(styles.nextButton, classNameNextBtn)}
            onClick={() => navigate("next")}
            aria-label={t("next")}
            title={t("next")}
          >
            <Icon name="chevron-right" />
          </button>
        )}
      </div>
      {navDots && showNavDots && carouselLastPage > 1 && (
        <div className={classNameNavDotsWrapper ? classNameNavDotsWrapper : styles.navDotsWrapper}>
          <NavDots
            currentPage={carouselPage}
            numberOfPages={carouselLastPage}
            handleNavDotClick={(page) => handleNavDotClick(page)}
          />
        </div>
      )}
    </div>
  );
};

const NavDots = ({
  currentPage,
  numberOfPages,
  handleNavDotClick,
}: {
  currentPage: number;
  numberOfPages: number;
  handleNavDotClick: (page: number) => void;
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const trackRef = useRef<HTMLDivElement>(null);
  const [overflowTranslateX, setOverflowTranslateX] = useState<number | null>(null);
  const recenter = useCallback(() => {
    const wrapper = containerRef.current;
    const track = trackRef.current;
    if (!wrapper || !track) return;

    const wrapperWidth = wrapper.clientWidth;
    const trackWidth = track.scrollWidth;

    // If everything fits, center via CSS
    if (trackWidth <= wrapperWidth) {
      setOverflowTranslateX(null);
      return;
    }

    const activeNavDot = track.querySelector<HTMLButtonElement>(`button[data-page="${currentPage}"]`);
    if (!activeNavDot) {
      return;
    }

    const trackRect = track.getBoundingClientRect();
    const navDotRect = activeNavDot.getBoundingClientRect();
    const activeCenter = navDotRect.left - trackRect.left + navDotRect.width / 2;
    let nextTranslate = wrapperWidth / 2 - activeCenter;

    // Clamp so we don't overscroll beyond edges
    const minTranslate = wrapperWidth - trackWidth;
    const maxTranslate = 0;
    nextTranslate = Math.min(maxTranslate, Math.max(minTranslate, nextTranslate));
    setOverflowTranslateX(nextTranslate);
  }, [currentPage]);

  useEffect(() => {
    recenter();
  }, [recenter, numberOfPages]);

  useEffect(() => {
    const onResize = () => recenter();
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, [recenter]);

  return (
    <div className={styles.navDots} ref={containerRef}>
      <div
        className={multipleClassNames(
          styles.navDotsTrackWrapper,
          overflowTranslateX !== null && styles.navDotsTrackWrapperOverflow,
        )}
      >
        <div
          className={styles.navDotsTrack}
          ref={trackRef}
          style={{ transform: `translateX(${overflowTranslateX}px)` }}
        >
          {Array.from({ length: numberOfPages }, (_, i) => {
            const page = i + 1;
            const isActive = currentPage === page;

            // calculate the scale and opacity of the dot based on how far away it is from the active page. The further away, the smaller and less opaque it is.
            const distance = Math.abs(currentPage - page);
            const totalDistance = Math.abs(numberOfPages - 1);
            const scale = Math.max(0.6, 1 - (distance / totalDistance) * 0.7);
            const opacity = Math.max(0.5, 1 - (distance / totalDistance) * 0.5);

            return (
              <button
                data-page={page}
                className={styles.navDotButton}
                aria-label={`Page ${page}`}
                key={`navdot-${page}`}
                onClick={() => handleNavDotClick(page)}
              >
                <motion.div
                  className={multipleClassNames(styles.navDot, isActive && styles.active)}
                  layout
                  animate={{ scale: scale, opacity: opacity }}
                  transition={{ type: "tween" }}
                />
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default Carousel;
